package org.jarvis.ans100.alpha.data

import android.content.Context

/**
 * Version-4 sparse topology for seven ANS-100 populations.
 *
 * Candidate and critic populations are split into six isolated lanes:
 * answer/support, answer/conflict, clarification/support, clarification/conflict,
 * abstain/support and abstain/conflict. Their readouts occupy separate halves
 * of each candidate's decision slot.
 *
 * The six lane labels are generated by the heuristic Core. The network routes
 * and counts these typed signals; it does not independently understand the
 * message or learn the support/conflict labels.
 */
object AndroidHybridTopologyV2 {
    const val TOPOLOGY_ID = "ans100-hybrid-v2"
    const val TOPOLOGY_VERSION = 4
    const val DATABASE_NAME = "jarvis_ans100_hybrid_v4.db"
    const val NEURON_COUNT = 10_000
    const val MAX_CONNECTION_COUNT = 100_000
    const val EXPECTED_CONNECTION_COUNT = 25_500
    const val CONNECTION_DELAY_NS = 1_000_000L
    const val FEED_FORWARD_WEIGHT = 1.0
    const val CONCEPT_ASSOCIATION_INITIAL_WEIGHT = 0.75
    const val RECURRENT_WEIGHT = 0.18
    private const val GENERAL_ASSOCIATION_SIZE = 1_000
    private const val EVIDENCE_GENERAL_FAN_OUT = 3
    private const val EVIDENCE_GENERAL_MULTIPLIER = 37L
    private const val EVIDENCE_GENERAL_SLOT_STEP = 113L
    private const val EVIDENCE_GENERAL_SALT = 11L

    data class Population(
        val id: String,
        val startInclusive: Int,
        val endExclusive: Int,
    ) {
        val size: Int get() = endExclusive - startInclusive
        fun contains(neuronId: Int): Boolean = neuronId in startInclusive until endExclusive
    }

    val populations: List<Population> = listOf(
        Population("evidence_input", 0, 1_200),
        Population("association", 1_200, 4_000),
        Population("working_state", 4_000, 5_800),
        Population("candidate", 5_800, 7_300),
        Population("critic_uncertainty", 7_300, 8_500),
        Population("goal_planning", 8_500, 9_400),
        Population("decision_readout", 9_400, 10_000),
    )

    fun open(
        context: Context,
        databaseName: String = DATABASE_NAME,
        hotSetCapacity: Int = AndroidSparseNeuronNetwork.DEFAULT_HOT_SET_CAPACITY,
    ): AndroidSparseNeuronNetwork {
        require(databaseName.matches(Regex("^[A-Za-z0-9._-]{1,128}\\.db$")))
        val network = AndroidSparseNeuronNetwork(context, databaseName, hotSetCapacity)
        try {
            network.initializeHybridTopologyV2()
            return network
        } catch (failure: Throwable) {
            network.close()
            throw failure
        }
    }

    /** Stable, bounded edge list; the v3 database is never reinterpreted as v4. */
    internal fun connections(): List<AndroidNeuronConnection> = buildList {
        val evidence = populations[0]
        val association = populations[1]
        val working = populations[2]
        val goal = populations[5]

        val generalAssociation = slice(association, 0, GENERAL_ASSOCIATION_SIZE, "association_general")
        val generalWorking = slice(working, 0, 300, "working_general")
        val candidateInputIds = (0 until ANS100CandidateSlotContract.INPUT_SIGNAL_COUNT)
            .map { ANS100CandidateSlotContract.INPUT_START + it }
            .toSet()

        // Ordinary evidence and approved concept inputs share the same exact
        // deterministic projection, but concept synapses start below the ceiling
        // so positive explicit feedback can strengthen them.
        val conceptInputIds = (ANS100ConceptMemory.NEURAL_INPUT_START until
            ANS100ConceptMemory.NEURAL_INPUT_START + ANS100ConceptMemory.MAX_NEURAL_INPUT_SLOTS).toSet()
        addProjection(
            "evidence-general-association",
            evidence,
            generalAssociation,
            fanOut = EVIDENCE_GENERAL_FAN_OUT,
            salt = EVIDENCE_GENERAL_SALT.toInt(),
            excludedSourceIds = candidateInputIds + conceptInputIds,
        )
        addProjection(
            "evidence-general-association",
            Population("concept_input", ANS100ConceptMemory.NEURAL_INPUT_START,
                ANS100ConceptMemory.NEURAL_INPUT_START + ANS100ConceptMemory.MAX_NEURAL_INPUT_SLOTS),
            generalAssociation,
            fanOut = EVIDENCE_GENERAL_FAN_OUT,
            salt = EVIDENCE_GENERAL_SALT.toInt(),
            feedForwardWeight = CONCEPT_ASSOCIATION_INITIAL_WEIGHT,
            sourceOffsetBase = ANS100ConceptMemory.NEURAL_INPUT_START - evidence.startInclusive,
        )
        ANS100CandidateSlotContract.Slot.values().forEach { slot ->
            ANS100CandidateSlotContract.Polarity.values().forEach { polarity ->
                val input = ANS100CandidateSlotContract.inputNeuronId(slot, polarity)
                addProjection(
                    "candidate-input-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    Population("candidate_input", input, input + 1),
                    ANS100CandidateSlotContract.associationLane(slot, polarity),
                    fanOut = 3,
                    salt = 17,
                )
            }
        }

        addProjection("association-general-recurrent", generalAssociation, generalAssociation, 1, 29, recurrent = true)
        addProjection("working-general-recurrent", generalWorking, generalWorking, 1, 61, recurrent = true)

        ANS100CandidateSlotContract.Slot.values().forEach { slot ->
            ANS100CandidateSlotContract.Polarity.values().forEach { polarity ->
                val associationLane = ANS100CandidateSlotContract.associationLane(slot, polarity)
                val workingLane = ANS100CandidateSlotContract.workingLane(slot, polarity)
                val candidateLane = ANS100CandidateSlotContract.candidateLane(slot, polarity)
                val criticLane = ANS100CandidateSlotContract.criticLane(slot, polarity)
                val readoutLane = ANS100CandidateSlotContract.readoutLane(slot, polarity)

                addProjection(
                    "association-${slot.name.lowercase()}-${polarity.name.lowercase()}-recurrent",
                    associationLane, associationLane, 1, 29,
                    recurrent = true,
                )
                addProjection(
                    "association-working-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    associationLane, workingLane, 2, 43,
                )
                addProjection(
                    "working-${slot.name.lowercase()}-${polarity.name.lowercase()}-recurrent",
                    workingLane, workingLane, 1, 61,
                    recurrent = true,
                )
                addProjection(
                    "working-candidate-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    workingLane, candidateLane, 2, 79,
                )
                addProjection(
                    "candidate-critic-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    candidateLane, criticLane, 2, 113,
                )
                addProjection(
                    "critic-candidate-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    criticLane, candidateLane, 1, 131,
                    recurrent = true,
                )
                addProjection(
                    "candidate-readout-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    candidateLane, readoutLane, 1, 149,
                )
                addProjection(
                    "critic-readout-${slot.name.lowercase()}-${polarity.name.lowercase()}",
                    criticLane, readoutLane, 1, 167,
                )
            }
        }

        // Shared evidence also feeds working state and goal planning, but the
        // goal lane is intentionally not wired into candidate readout slots.
        addProjection("association-general-working", generalAssociation, generalWorking, 2, 43)
        addProjection("working-to-goal", working, goal, 1, 97)
    }.also { edges ->
        require(edges.size == EXPECTED_CONNECTION_COUNT) {
            "candidate-slot topology edge count mismatch: ${edges.size}"
        }
        require(edges.size <= MAX_CONNECTION_COUNT)
        require(edges.map { it.connectionId }.toSet().size == edges.size)
    }

    /**
     * Returns the exact three targets used by the evidence-general-association
     * projection for a concept input neuron. This mirrors addProjection() below;
     * it does not create edges or infer a relation.
     */
    fun conceptAssociationProjection(neuronId: Int): Map<Int, String> {
        val evidence = populations[0]
        require(neuronId in ANS100ConceptMemory.NEURAL_INPUT_START until
            ANS100ConceptMemory.NEURAL_INPUT_START + ANS100ConceptMemory.MAX_NEURAL_INPUT_SLOTS) {
            "neuron is outside the reserved concept-input range"
        }
        require(evidence.contains(neuronId))
        val associationStart = populations[1].startInclusive
        val associationSize = GENERAL_ASSOCIATION_SIZE
        return (0 until EVIDENCE_GENERAL_FAN_OUT).associate { slot ->
            val sourceOffset = neuronId - evidence.startInclusive
            val targetOffset = (
                sourceOffset.toLong() * EVIDENCE_GENERAL_MULTIPLIER +
                    slot.toLong() * EVIDENCE_GENERAL_SLOT_STEP +
                    EVIDENCE_GENERAL_SALT
                ) % associationSize
            val targetId = associationStart + targetOffset.toInt()
            targetId to "ans100-v4-evidence-general-association-$neuronId-$targetId"
        }
    }

    fun conceptAssociationTargets(neuronId: Int): Set<Int> =
        conceptAssociationProjection(neuronId).keys

    private fun slice(
        population: Population,
        offset: Int,
        size: Int,
        id: String,
    ): Population {
        require(offset >= 0 && size > 0 && offset + size <= population.size)
        val start = population.startInclusive + offset
        return Population(id, start, start + size)
    }

    private fun MutableList<AndroidNeuronConnection>.addProjection(
        kind: String,
        source: Population,
        target: Population,
        fanOut: Int,
        salt: Int,
        recurrent: Boolean = false,
        excludedSourceIds: Set<Int> = emptySet(),
        feedForwardWeight: Double = FEED_FORWARD_WEIGHT,
        sourceOffsetBase: Int = 0,
    ) {
        require(fanOut in 1..8)
        for (sourceOffset in 0 until source.size) {
            val sourceId = source.startInclusive + sourceOffset
            if (sourceId in excludedSourceIds) continue
            val usedTargets = HashSet<Int>(fanOut)
            for (slot in 0 until fanOut) {
                val topologySourceOffset = sourceOffset.toLong() + sourceOffsetBase
                var targetOffset = (topologySourceOffset * 37L + slot.toLong() * 113L + salt) % target.size
                var targetId = target.startInclusive + targetOffset.toInt()
                if (recurrent && targetId == sourceId) {
                    targetOffset = (targetOffset + 1L) % target.size
                    targetId = target.startInclusive + targetOffset.toInt()
                }
                while (!usedTargets.add(targetId)) {
                    targetOffset = (targetOffset + 1L) % target.size
                    targetId = target.startInclusive + targetOffset.toInt()
                }
                add(
                    AndroidNeuronConnection(
                        connectionId = "ans100-v4-$kind-$sourceId-$targetId",
                        sourceNeuronId = sourceId,
                        targetNeuronId = targetId,
                        delayNs = CONNECTION_DELAY_NS,
                        weight = if (recurrent) RECURRENT_WEIGHT else feedForwardWeight,
                    ),
                )
            }
        }
    }
}
